package com.oms.inventory;
import com.oms.inventory.service.impl.StockProcessService;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class StockProcessTest {
 OrderStockTest f;StockProcessService service;
 @BeforeAll static void start(){OrderStockTest.start();}
 @AfterAll static void stop(){OrderStockTest.stop();}
 @BeforeEach void setup(){f=new OrderStockTest();f.clear();for(String table:Arrays.asList("oms_stock_process_event","oms_stock_process_hold","oms_stock_process_origin","oms_stock_process"))f.db.update("DELETE FROM "+table);service=f.context.getBean(StockProcessService.class);f.seed(20,0);f.db.update("UPDATE wms_inventory_batch SET transaction_price=2.50 WHERE sku_sn='A'");f.db.update("INSERT INTO oms_inventory(company_code,sku_sn,total_stock,available_stock,version) VALUES ('VERIFY','B',10,10,1)");f.db.update("INSERT INTO wms_inventory(company_code,sku_sn,store_code,zp_actual_number,zp_available_number,version) VALUES ('VERIFY','B','W1',10,10,1)");f.db.update("INSERT INTO wms_inventory_batch(company_code,sku_sn,store_code,batch_code,zp_actual_number,zp_available_number,transaction_price,version) VALUES ('VERIFY','B','W1','B1',10,10,4.50,1)");}
 Map<String,Object> m(Object...a){Map<String,Object> r=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)r.put(a[i].toString(),a[i+1]);return r;}
 Map<String,Object> recipe(){return m("sku_sn","S","inventory_mode","STOCKED","revision",1,"components",Arrays.asList(m("sku_sn","A","quantity",2),m("sku_sn","B","quantity",1)));}
 Map<String,Object> reserve(String sn,int q){return m("process_sn",sn,"operation","ASSEMBLE","store_code","W1","quantity",q,"recipe",recipe());}
 Map<String,Object> line(String sku,String batch,int q){return m("sku_sn",sku,"batch_code",batch,"quantity",q,"inventory_type","ZP");}
 Map<String,Object> post(String sn,String msg,int q){return m("process_sn",sn,"message_id",msg,"quantity",q,"inputs",Arrays.asList(line("A","B1",q*2),line("B","B1",q)),"outputs",Arrays.asList(line("S","FIN_"+msg,q)),"reviewed",false);}
 long n(String sql){return f.n(sql);}
 @Test void reserveDoesNotChangePhysicalStockAndPartialReceiptConvertsBothSidesExactlyOnce(){Map<String,Object> cmd=reserve("JGTEST1",4);service.execute("VERIFY","reserve",cmd);service.execute("VERIFY","reserve",cmd);assertEquals(20,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(8,n("SELECT allocated_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(0,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));Map<String,Object> receipt=post("JGTEST1","E1",2);service.execute("VERIFY","post",receipt);service.execute("VERIFY","post",receipt);receipt.put("reviewed",true);service.execute("VERIFY","post",receipt);assertEquals(16,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(8,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='B'"));assertEquals(2,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals(4,n("SELECT zp_lock_number FROM wms_inventory_batch WHERE sku_sn='A'"));assertEquals(1,n("SELECT COUNT(*) FROM oms_stock_process_event"));assertEquals(950,n("SELECT transaction_price*100 FROM wms_inventory_batch WHERE sku_sn='S'"));service.execute("VERIFY","post",post("JGTEST1","E2",2));assertEquals(4,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals(0,n("SELECT SUM(zp_lock_number) FROM wms_inventory_batch"));}
 @Test void outputFailureRollsBackAllInputConsumption(){service.execute("VERIFY","reserve",reserve("JGTEST2",2));Map<String,Object> bad=post("JGTEST2","BAD",1);bad.put("outputs",Arrays.asList(line("S","",1)));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","post",bad));assertEquals(20,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(4,n("SELECT zp_lock_number FROM wms_inventory_batch WHERE sku_sn='A'"));assertEquals(0,n("SELECT COUNT(*) FROM oms_stock_process_event"));}
 @Test void cancellationRetainsCompletedStockAndReleasesOnlyUnusedInputs(){service.execute("VERIFY","reserve",reserve("JGTEST3",4));service.execute("VERIFY","post",post("JGTEST3","E3",1));service.execute("VERIFY","release",m("process_sn","JGTEST3"));service.execute("VERIFY","release",m("process_sn","JGTEST3"));assertEquals(18,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(18,n("SELECT available_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(1,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals(0,n("SELECT SUM(zp_lock_number) FROM wms_inventory_batch"));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","post",post("JGTEST3","LATE",1)));}
 @Test void sourceBatchDisassemblyRecoversComponentsAtOriginalCosts(){service.execute("VERIFY","reserve",reserve("JGTEST4",2));service.execute("VERIFY","post",post("JGTEST4","E4",2));long batch=n("SELECT id FROM wms_inventory_batch WHERE sku_sn='S'");Map<String,Object> origin=service.origin("VERIFY",batch);service.execute("VERIFY","reserve",m("process_sn","JGTEST5","operation","DISASSEMBLE","store_code","W1","quantity",1,"source_batch_id",batch,"recipe",origin.get("recipe")));service.execute("VERIFY","post",m("process_sn","JGTEST5","message_id","D1","quantity",1,"inputs",Arrays.asList(line("S","FIN_E4",1)),"outputs",Arrays.asList(line("A","BACK_A",2),line("B","BACK_B",1)),"reviewed",false));assertEquals(18,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(9,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='B'"));assertEquals(1,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals(250,n("SELECT transaction_price*100 FROM wms_inventory_batch WHERE batch_code='BACK_A'"));}
 @Test void publicOrderReservationsCannotBeStolenAndCrossCompanyHasNoAccess(){f.execute("register",f.command("8000",19,true));f.execute("reserve",f.command("8000",19,true));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","reserve",reserve("JGTEST6",1)));assertEquals(0,n("SELECT COUNT(*) FROM oms_stock_process"));assertThrows(IllegalArgumentException.class,()->service.origin("OTHER",n("SELECT MIN(id) FROM wms_inventory_batch")));}
 @Test void sameMessageChangedQuantityCannotConsumeTwice(){service.execute("VERIFY","reserve",reserve("JGTEST7",4));service.execute("VERIFY","post",post("JGTEST7","X",1));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","post",post("JGTEST7","X",2)));assertEquals(1,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));}
 @Test void damagedOutputIsNotSellableAndDiscrepancyNeedsExplicitReview(){service.execute("VERIFY","reserve",reserve("JGTEST8",1));Map<String,Object> cmd=post("JGTEST8","DIFF",1);cmd.put("inputs",Arrays.asList(line("A","B1",1),line("B","B1",1)));cmd.put("outputs",Arrays.asList(m("sku_sn","S","batch_code","DAMAGED","quantity",1,"inventory_type","CC")));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","post",cmd));cmd.put("reviewed",true);service.execute("VERIFY","post",cmd);assertEquals(0,n("SELECT available_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals(1,n("SELECT frozen_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals(0,n("SELECT SUM(zp_lock_number) FROM wms_inventory_batch"));}
 @Test void confirmedLateWorkCanRecoverOnlyOriginalReleasedFreeBatches(){service.execute("VERIFY","reserve",reserve("JGLATE",2));service.execute("VERIFY","release",m("process_sn","JGLATE"));Map<String,Object> late=post("JGLATE","LATE_CONFIRMED",1);assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","post",late));late.put("reviewed",true);service.execute("VERIFY","post",late);service.execute("VERIFY","post",late);assertEquals(18,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(1,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals("STOPPED",service.report("VERIFY","JGLATE").get("state"));assertEquals(0,n("SELECT SUM(zp_lock_number) FROM wms_inventory_batch"));}
 @Test void lateWorkCannotTakeStockAlreadyReservedByAnotherOrder(){service.execute("VERIFY","reserve",reserve("JGLATE2",2));service.execute("VERIFY","release",m("process_sn","JGLATE2"));f.execute("register",f.command("9000",19,true));f.execute("reserve",f.command("9000",19,true));Map<String,Object> late=post("JGLATE2","LATE_CONFLICT",1);late.put("reviewed",true);assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","post",late));assertEquals(20,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='A'"));assertEquals(0,n("SELECT total_stock FROM oms_inventory WHERE sku_sn='S'"));assertEquals(19,n("SELECT reserved_stock FROM oms_inventory WHERE sku_sn='A'"));}
}
